from .money import MAX_CENTS, to_cents, cents_to_amount, format_amount


def make_invoice(amounts):
    # Strict check: only a plain Python list (not a tuple, str, None, or subclass).
    if type(amounts) is not list:
        raise ValueError("amounts must be a list")

    # Sum integer cents so the total is exact regardless of decimal precision.
    total_cents = 0
    for item in amounts:
        total_cents += to_cents(item)

    if total_cents > MAX_CENTS:
        raise ValueError("total exceeds 1000000.00")

    total = cents_to_amount(total_cents)
    return {"total": format_amount(total), "count": len(amounts)}

